text:
{
  "title": "شروط وأحكام استخدام تطبيق شركة آفاق الحلول الذكية",
  "planted": [
    {
      "slot": "p1",
      "text": "للاستفادة من الخدمات الأساسية وتفعيل حساب المستخدم، يشترط تقديم صورة كاملة لبطاقة الهوية الوطنية، وتحديد الحالة الاجتماعية، وعدد أفراد الأسرة، وجهة العمل الحالية، وذلك لضمان تقديم تجربة مخصصة ودقيقة."
    },
    {
      "slot": "p2",
      "text": "لا يحق للمستخدم بأي حال من الأحوال طلب الاطلاع على البيانات الشخصية المحفوظة لدى النظام أو تعديلها، كما لا تقبل الشركة أي طلبات لحذف أو إتلاف تلك البيانات بعد إتمام عملية التسجيل."
    },
    {
      "slot": "p3",
      "text": "تحتفظ الشركة بحق استخدام البيانات والمعلومات المجمعة لأي غرض تراه مناسباً ضمن نطاق أعمالها التشغيلية الحالية والمستقبلية، بما في ذلك التطوير الداخلي وتقديم خدمات جديدة."
    },
    {
      "slot": "p4",
      "text": "قبل إتمام عملية إنشاء الحساب، توفر الشركة وثيقة سياسة الخصوصية التي توضح أنواع البيانات التي يتم جمعها، وأساليب معالجتها وتخزينها وإتلافها، بالإضافة إلى بيان الحقوق العامة وآلية التواصل بشأنها."
    },
    {
      "slot": "p5",
      "text": "يقر المستخدم بموافقته على معالجة البيانات المجمعة واستخدامها وفقاً للآليات التشغيلية المعتمدة لدى الشركة، على أن يتم التعامل مع طلبات التعديل أو التغيير وفقاً للمتطلبات الإدارية المتبعة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية المتمثلة في رسوم الاشتراكات والخدمات عبر التطبيق لآليات الدفع الإلكتروني المعتمدة، ولا ترد الرسوم بعد إتمام عملية التحويل بنجاح.",
    "تبدأ المدة الزمنية لهذا الاتفاق اعتباراً من تاريخ قبول الشروط وإنشاء الحساب، وتستمر حتى قيام إحدى الطرفين بإنهاء التعاقد وفقاً للإجراءات المحددة في التطبيق.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناشئة عن استخدام التطبيق أو تعطل الخدمة لأسباب خارجة عن إرادتها التشغيلية.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية المختصة بالفصل في أي نزاع قد ينشأ عنها.",
    "يقصد بالتعابير الواردة في هذه الشروط المعاني المخصصة لها، حيث يشير مصطلح التطبيق إلى منصة آفاق الحلول الذكية، ويشير مصطلح المستخدم إلى كل شخص ينشئ حساباً فعالاً.",
    "تعتبر كافة حقوق الملكية الفكرية والعلامات التجارية والتصاميم والنصوص البرمجية الخاصة بالتطبيق ملكاً خالصاً للشركة، ولا يجوز نسخها أو استخدامها دون إذن خطي مسبق.",
    "تتم عملية تسليم المنتجات الرقمية أو تفعيل الخدمات المتاحة عبر التطبيق إلكترونياً بشكل فوري بعد تأكيد الدفع، ولا تلتزم الشركة بأي تسليم خارج نطاق المنصة.",
    "توجه كافة الإشعارات والمخاطبات الرسمية الموجهة للشركة عبر وسائل الاتصال المعتمدة داخل التطبيق أو عبر البريد الإلكتروني الرسمي للعملاء المكتوب في الحساب."
  ]
}
